def can_chain(dominoes):
    """Return a closed chain using every domino, or None if impossible.

    A valid chain orders all dominoes so that neighboring halves match,
    and the free end of the last stone matches the free end of the first.
    Dominoes may be flipped.
    """

    def backtrack(remaining, chain, first):
        if not remaining:
            return chain if chain[-1][1] == first else None
        last = chain[-1][1]
        for i, (a, b) in enumerate(remaining):
            rest = remaining[:i] + remaining[i + 1:]
            for d in ((a, b), (b, a)):
                if d[0] == last:
                    result = backtrack(rest, chain + [d], first)
                    if result is not None:
                        return result
        return None

    if not dominoes:
        return []

    for i, (a, b) in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        for d in ((a, b), (b, a)):
            result = backtrack(rest, [d], d[0])
            if result is not None:
                return result
    return None

